import { AnimatePresence } from "motion/react";
import * as m from "motion/react-m";
import { useEffect, useState } from "react";
import { useAgentChatSummaries } from "@/hooks/useAgentChat";
import { useAgents } from "@/hooks/useAgents";
import { useIsDesktop } from "@/hooks/useIsDesktop";
import { getChat, setActiveChat } from "@/lib/chats";
import { backdrop } from "@/lib/motion";
import { ChatPane } from "@/shell/ChatPane";
import { Sidebar } from "@/shell/Sidebar";

const ACTIVE_KEY = "nlhack.activeAgent";
const COLLAPSED_KEY = "nlhack.sidebarCollapsed";

function readPref(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

function writePref(key: string, value: string) {
  try {
    localStorage.setItem(key, value);
  } catch {
    // Preferences are a convenience; ignore blocked storage.
  }
}

export function App() {
  const agents = useAgents();
  // ?agent=<key|id> deep-links to an agent; otherwise reopen the last one.
  const [activeKey, setActiveKey] = useState<string | null>(
    () => new URLSearchParams(window.location.search).get("agent") ?? readPref(ACTIVE_KEY),
  );
  const [collapsed, setCollapsed] = useState(() => readPref(COLLAPSED_KEY) === "true");
  const [mobileOpen, setMobileOpen] = useState(false);
  const isDesktop = useIsDesktop();
  // Docked on desktop unless collapsed; an overlay on mobile only while open.
  const sidebarOpen = isDesktop ? !collapsed : mobileOpen;
  const overlayOpen = !isDesktop && mobileOpen;

  const active =
    agents.find((agent) => agent.key === activeKey || agent.id === activeKey) ?? agents[0] ?? null;
  const rows = useAgentChatSummaries(agents.map((agent) => agent.key));
  useEffect(() => {
    setActiveChat(active?.key ?? null);
  }, [active?.key]);

  const select = (key: string) => {
    setActiveKey(key);
    writePref(ACTIVE_KEY, key);
    setMobileOpen(false);
  };
  const setCollapsedPref = (value: boolean) => {
    setCollapsed(value);
    writePref(COLLAPSED_KEY, String(value));
  };

  return (
    <div className="relative flex h-full min-w-0 overflow-hidden bg-background text-foreground/90">
      <AnimatePresence initial={false}>
        {overlayOpen ? (
          <m.button
            key="backdrop"
            type="button"
            aria-label="Close navigation"
            onClick={() => setMobileOpen(false)}
            variants={backdrop}
            initial="hidden"
            animate="visible"
            exit="hidden"
            className="absolute inset-y-0 end-0 start-[min(calc(100%-48px),284px)] z-30 bg-overlay"
          />
        ) : null}
      </AnimatePresence>
      <AnimatePresence initial={false}>
        {sidebarOpen ? (
          <Sidebar
            key={isDesktop ? "docked" : "overlay"}
            docked={isDesktop}
            agents={agents}
            rows={rows}
            activeKey={active?.key ?? null}
            onSelect={select}
            onNewChat={() => {
              if (active) {
                const chat = getChat(active.key);
                void chat.stop();
                chat.clearError();
                chat.messages = [];
              }
              setMobileOpen(false);
            }}
            onCollapse={() => setCollapsedPref(true)}
          />
        ) : null}
      </AnimatePresence>
      <main
        aria-hidden={overlayOpen || undefined}
        inert={overlayOpen}
        className="isolate flex min-w-0 flex-1 flex-col bg-background"
      >
        <ChatPane
          agent={active}
          agents={agents}
          sidebarCollapsed={isDesktop && collapsed}
          onOpenMobileSidebar={() => setMobileOpen(true)}
          onRestoreSidebar={() => setCollapsedPref(false)}
        />
      </main>
    </div>
  );
}
import { useEffect, useState } from "react";

export type AgentSummary = {
  /** Mastra registry key (e.g. "marketResearcher"). */
  key: string;
  /** Agent id (e.g. "market-researcher"); also the avatar identity. */
  id: string;
  name: string;
  description: string;
};

/** Mirrors GET /api/agents; used until it answers, or when it can't (e.g. standalone `vite`). */
export const FALLBACK_AGENTS: AgentSummary[] = [
  {
    key: "assistant",
    id: "assistant",
    name: "Assistant",
    description: "Primary assistant that handles conversations and coordinates specialist agents.",
  },
  {
    key: "marketResearcher",
    id: "market-researcher",
    name: "Market Researcher",
    description:
      "Researches companies, competitors, pricing, funding, headcount, and market trends using Crustdata and live web search.",
  },
  {
    key: "cfoAgent",
    id: "cfo",
    name: "CFO Agent",
    description:
      "Analyzes business financials, cash flow, runway, budgets, pricing, unit economics, and hiring scenarios.",
  },
];

function isAgentList(value: unknown): value is AgentSummary[] {
  return (
    Array.isArray(value) &&
    value.every(
      (agent) =>
        agent && typeof agent.key === "string" && typeof agent.id === "string" && typeof agent.name === "string",
    )
  );
}

export function useAgents(): AgentSummary[] {
  const [agents, setAgents] = useState(FALLBACK_AGENTS);
  useEffect(() => {
    const abort = new AbortController();
    fetch("/api/agents", { signal: abort.signal })
      .then((res) => (res.ok ? res.json() : null))
      .then((list: unknown) => {
        if (isAgentList(list) && list.length > 0) setAgents(list);
      })
      .catch(() => undefined);
    return () => abort.abort();
  }, []);
  return agents;
}
// Layout and classes ported from rakazo's bots sidebar (apps/web/src/pages/Shell.tsx ~2811-3263),
// Apache-2.0, github.com/elie222/rakazo@912c977. Groups, spaces, archive and the user menu are stripped.
import { Moon, PanelLeftClose, Search, SquarePen, Sun } from "lucide-react";
import { AnimatePresence, useReducedMotion, type Variants } from "motion/react";
import * as m from "motion/react-m";
import { useState } from "react";
import { BotAvatar } from "@/components/avatar/bot-avatar";
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group";
import type { AgentRowState } from "@/hooks/useAgentChat";
import type { AgentSummary } from "@/hooks/useAgents";
import { agentAvatarValue } from "@/lib/agent-avatar";
import { type ResolvedAppearance, setUiAppearance } from "@/lib/appearance";
import { messageTime } from "@/lib/chats";
import {
  DURATION,
  enterTransition,
  exitTransition,
  fade,
  instant,
  pop,
  SIDEBAR_WIDTH,
  SPRING,
  STAGGER,
  STAGGER_CAP,
  sidebarContent,
  sidebarDesktop,
  sidebarMobile,
} from "@/lib/motion";

/** Rows rise in one after another; a filtered-out row leaves the way it came. */
const rowVariants: Variants = {
  hidden: { opacity: 0, y: 6, transition: exitTransition(DURATION.base) },
  visible: (index: number = 0) => ({
    opacity: 1,
    y: 0,
    transition: enterTransition(DURATION.base, Math.min(index, STAGGER_CAP) * STAGGER),
  }),
